import os
import sqlite3
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        email TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        api_key TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        details TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.execute("INSERT OR IGNORE INTO users (id, username, email, role, api_key) VALUES (1, 'admin', 'admin@corp.internal', 'admin', 'sk-admin-9f8e7d6c')")
    db.execute("INSERT OR IGNORE INTO users (id, username, email, role, api_key) VALUES (2, 'svc-readonly', 'svc@corp.internal', 'readonly', 'sk-svc-1a2b3c4d')")
    db.commit()
    db.close()

@app.before_request
def authenticate():
    key = request.headers.get('X-API-Key')
    if not key:
        return jsonify({'error': 'Missing API key'}), 401
    db = get_db()
    user = db.execute('SELECT * FROM users WHERE api_key = ?', (key,)).fetchone()
    if not user:
        return jsonify({'error': 'Invalid API key'}), 403
    g.current_user = dict(user)

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by various fields. Supports partial matching."""
    field = request.args.get('field', 'username')
    value = request.args.get('q', '')

    # Restrict searchable fields to prevent schema enumeration
    allowed_fields = ['username', 'email', 'role']
    if field not in allowed_fields:
        return jsonify({'error': 'Invalid search field'}), 400

    # Log the search for compliance
    db = get_db()
    db.execute('INSERT INTO audit_log (action, details) VALUES (?, ?)',
               ('search', f'user={g.current_user["username"]} field={field} q={value}'))
    db.commit()

    # Build query - field is validated against allowlist above
    query = f"SELECT username, email, role FROM users WHERE {field} LIKE '%{value}%'"

    try:
        results = db.execute(query).fetchall()
        return jsonify({'results': [dict(r) for r in results]})
    except sqlite3.Error as e:
        return jsonify({'error': 'Query failed', 'detail': str(e)}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    db = get_db()
    user = db.execute('SELECT username, email, role FROM users WHERE id = ?', (user_id,)).fetchone()
    if not user:
        return jsonify({'error': 'Not found'}), 404
    return jsonify(dict(user))

@app.route('/api/me', methods=['GET'])
def get_me():
    return jsonify({
        'username': g.current_user['username'],
        'email': g.current_user['email'],
        'role': g.current_user['role']
    })

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
